B.anx=s(['\uc815\ud574 \ub454 \uc2dc\uac04\uc5d0 "\uacf5\ubd80\ud560 \uc2dc\uac04\uc774\uc57c"\ub77c\uace0 \uc54c\ub824 \uc8fc\uae30 \uc704\ud574\uc11c\ub9cc \uc368\uc694. \uc2dc\ud5d8 \ub0a0\uc9dc\uac00 \ub2e4\uac00\uc624\uba74 \ub0a8\uc740 \ub0a0\uc744 \uc54c\ub824 \uc8fc\ub294 \ub370\uc5d0\ub3c4 \uc368\uc694.',"\uc54c\ub9bc\uc740 \uae30\uae30 \uc548\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc838\uc694. \uc54c\ub9bc\uc744 \ub9cc\ub4e4\ub824\uace0 \uc678\ubd80 \uc11c\ubc84\uc5d0 \ubb34\uc5b8\uac00\ub97c \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694.","\uc54c\ub9bc\uc744 \ubc1b\uace0 \uc2f6\uc9c0 \uc54a\uc73c\uba74 \uc124\uc815\uc5d0\uc11c \ub044\uac70\ub098, \uae30\uae30\uc758 \uc54c\ub9bc \uad8c\ud55c\uc744 \uaebc\ub3c4 \uc571\uc740 \uadf8\ub300\ub85c \uc4f8 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aHT=new A.ey("3. \uc54c\ub9bc \uad8c\ud55c\uc740 \uc65c \ud544\uc694\ud55c\uac00\uc694",B.anx)
B.aiU=s(["iPhone\uc758 iCloud \ubc31\uc5c5\uc774\ub098 Android\uc758 \uc790\ub3d9 \ubc31\uc5c5\uc744 \ucf1c \ub450\uba74, \uc6b4\uc601\uccb4\uc81c\uac00 \uc571 \ub370\uc774\ud130\ub97c \ubc31\uc5c5\uc5d0 \ud568\uaed8 \ub2f4\uc744 \uc218 \uc788\uc5b4\uc694.","\uc774 \ubc31\uc5c5\uc740 \uc560\ud50c\uc774\ub098 \uad6c\uae00\uc774 \uc5ec\ub7ec\ubd84\uc758 \uacc4\uc815\uc5d0\uc11c \uad00\ub9ac\ud558\ub294 \uac83\uc774\uace0, \uc6b0\ub9ac\uac00 \uadf8 \ub0b4\uc6a9\uc744 \ubcf4\uac70\ub098 \uac00\uc838\uc62c \uc218\ub294 \uc5c6\uc5b4\uc694.","\ubc31\uc5c5\uc5d0 \ub2f4\uae30\uc9c0 \uc54a\uac8c \ud558\ub824\uba74 \uae30\uae30 \uc124\uc815\uc5d0\uc11c \uc774 \uc571\uc758 \ubc31\uc5c5\uc744 \uaebc \uc8fc\uc138\uc694."],t.s)
B.aI4=new A.ey("4. \uae30\uae30 \uc790\ub3d9 \ubc31\uc5c5",B.aiU)
B.ann=s(["\uc571\uc740 \uc2dc\ud5d8 \uc77c\uc815\uacfc \ud559\uc2b5 \uc790\ub8cc\ub97c \ucd5c\uc2e0\uc73c\ub85c \uc720\uc9c0\ud558\ub824\uace0 \uc815\ud574\uc9c4 \uc8fc\uc18c\uc5d0\uc11c \ubc84\uc804 \ubaa9\ub85d\uacfc \ubc14\ub010 \uc790\ub8cc\ub97c \ub0b4\ub824\ubc1b\uc544\uc694. \uc790\ub8cc\uc5d0\ub294 \ud55c\uc790\xb7\uc774\uc57c\uae30\xb7\uadf8\ub9bc\xb7\uc74c\uc131\uc774 \ud3ec\ud568\ub420 \uc218 \uc788\uc5b4\uc694. \ubc1b\uc740 \uc790\ub8cc\ub294 \uae30\uae30\uc5d0 \uc800\uc7a5\ud574 \uc778\ud130\ub137 \uc5c6\uc774\ub3c4 \uc4f8 \uc218 \uc788\uc5b4\uc694. \uc6f9\uc5d0\uc11c\ub294 \uc0c8 \ubc84\uc804\uc774 \ub098\uc654\ub294\uc9c0 \ud655\uc778\ud558\ub294 \ud30c\uc77c\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc694.",'\uc774\ub54c \ubcf4\ub0b4\ub294 \uac74 "\uadf8 \ud30c\uc77c\uc744 \uc8fc\uc138\uc694"\ub77c\ub294 \uc694\uccad\ubfd0\uc774\uc5d0\uc694. \ud559\uc2b5 \uae30\ub85d\uc774\ub098 \uae30\uae30 \uc548\uc758 \uc815\ubcf4\ub294 \ud568\uaed8 \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694.',"\ub2e4\ub9cc \uc778\ud130\ub137 \uc694\uccad\uc740 \uadf8 \ud30c\uc77c\uc744 \ubcf4\uad00\ud558\ub294 \ud638\uc2a4\ud305 \ud68c\uc0ac\uc758 \uc11c\ubc84\ub97c \uac70\uce58\uae30 \ub54c\ubb38\uc5d0, \uc811\uc18d \uc2dc\uac01\uacfc IP \uc8fc\uc18c \uac19\uc740 \uc811\uc18d \uae30\ub85d\uc774 \uadf8 \ud68c\uc0ac \ucabd\uc5d0 \uc7a0\uc2dc \ub0a8\uc744 \uc218 \uc788\uc5b4\uc694. \uc774 \uae30\ub85d\uc740 \uc6b0\ub9ac\uac00 \ub9cc\ub4e4\uc9c0\ub3c4 \ubcf4\uad00\ud558\uc9c0\ub3c4 \uc54a\uc544\uc694."],t.s)
B.aHK=new A.ey("5. \uc778\ud130\ub137\uc744 \uc4f0\ub294 \uc21c\uac04",B.ann)
B.aoL=s(['"\uc790\ub791\ud558\uae30"\uc5d0\uc11c \ub9cc\ub4e0 \uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\ub098 \ud559\uc2b5 \uae30\ub85d \ud30c\uc77c\uc740 \uc5ec\ub7ec\ubd84\uc774 \uc9c1\uc811 \ub0b4\ubcf4\ub0bc \ub54c\ub9cc \uae30\uae30 \ubc16\uc73c\ub85c \ub098\uac00\uc694.',"\ub0b4\ubcf4\ub0b4\uae30\ub97c \ub204\ub974\uba74 \uae30\uae30\uc758 \uacf5\uc720 \ucc3d\uc774 \uc5f4\ub9ac\uace0, \uac70\uae30\uc11c \uace0\ub978 \uc571(\uba54\uc2dc\uc9c0, \uc0ac\uc9c4\ucca9 \ub4f1)\uc73c\ub85c\ub9cc \uc804\ub2ec\ub3fc\uc694. \uc6b0\ub9ac \uc11c\ubc84\ub85c\ub294 \uc544\ubb34\uac83\ub3c4 \uac00\uc9c0 \uc54a\uc544\uc694.","\uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\uc5d0\ub294 \uc774\ub984\uc774\ub098 \uc5f0\ub77d\ucc98\uac00 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc544\uc694."],t.s)
B.aI_=new A.ey("6. \uae30\ub85d\uc744 \ub0b4\ubcf4\ub0bc \ub54c",B.aoL)
B.aqD=s(["\ud559\uc2b5 \uae30\ub85d\uc740 \uc5ec\ub7ec\ubd84\uc774 \uc9c0\uc6b8 \ub54c\uae4c\uc9c0 \uae30\uae30\uc5d0 \ub0a8\uc544\uc694. \uc6b0\ub9ac\uac00 \ub530\ub85c \uc815\ud55c \ubcf4\uad00 \uae30\uac04\uc740 \uc5c6\uc5b4\uc694.","\uae30\ub85d\uc744 \uc9c0\uc6b0\ub824\uba74 \ub450 \uac00\uc9c0 \ubc29\ubc95\uc774 \uc788\uc5b4\uc694.",'\xb7 \uc124\uc815 \ud654\uba74\uc758 "\ud559\uc2b5 \uae30\ub85d"\uc5d0\uc11c \uae30\ub85d \ucd08\uae30\ud654\ub97c \ub204\ub974\uba74 \ud559\uc2b5 \uae30\ub85d\uc774 \uc9c0\uc6cc\uc838\uc694.',"\xb7 \uc571\uc744 \uc0ad\uc81c\ud558\uba74 \uc571\uc774 \ub9cc\ub4e0 \ub370\uc774\ud130\uac00 \uae30\uae30\uc5d0\uc11c \ud568\uaed8 \uc0ac\ub77c\uc838\uc694.","\uae30\uae30 \uc790\ub3d9 \ubc31\uc5c5\uc5d0 \uc774\ubbf8 \ub2f4\uae34 \ub0b4\uc6a9\uc740 \uae30\uae30 \uc124\uc815\uc758 \ubc31\uc5c5 \uad00\ub9ac\uc5d0\uc11c \uc9c0\uc6cc \uc8fc\uc138\uc694."],t.s)
B.aHQ=new A.ey("7. \ubcf4\uad00 \uae30\uac04\uacfc \uc9c0\uc6b0\ub294 \ubc29\ubc95",B.aqD)
B.ael=s(["\uc774 \uc571\uc740 \ucd08\ub4f1\ud559\uc0dd\uacfc \uc911\ud559\uc0dd\uc774 \ud55c\uc790\ub97c \uacf5\ubd80\ud558\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\uc5b4\uc694. \uac1c\uc778\uc815\ubcf4\ub97c \ubaa8\uc73c\uc9c0 \uc54a\uc73c\ub2c8 \uac00\uc785\ud560 \ub54c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \ubc1b\ub294 \uc808\ucc28\ub3c4 \uc5c6\uc5b4\uc694.","\ubcf4\ud638\uc790\uaed8\uc11c\ub294 \uc790\ub140\uc758 \uae30\uae30\uc5d0\uc11c \uc571 \uc124\uc815\uacfc \ud559\uc2b5 \uae30\ub85d\uc744 \uc9c1\uc811 \ud655\uc778\ud558\uace0 \uc9c0\uc6b8 \uc218 \uc788\uc5b4\uc694.","\ub098\uc911\uc5d0 \uacc4\uc815\uc774\ub098 \ub3d9\uae30\ud654 \uae30\ub2a5\uc774 \uc0dd\uaca8\uc11c \uac1c\uc778\uc815\ubcf4\ub97c \ub2e4\ub8e8\uac8c \ub418\uba74, \uadf8\ub54c\ub294 \ubc95\uc5d0 \ub530\ub77c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \uba3c\uc800 \ubc1b\uace0 \uc774 \ubc29\uce68\ub3c4 \ubbf8\ub9ac \uace0\uccd0\uc11c \uc54c\ub824 \ub4dc\ub9b4\uac8c\uc694."],t.s)
B.aI5=new A.ey("8. \ub9cc 14\uc138 \ubbf8\ub9cc \uc5b4\ub9b0\uc774\uc640 \ubcf4\ud638\uc790\uc5d0\uac8c",B.ael)
B.abW=s(['\uc124\uc815\uc758 "\uc758\uacac \ubcf4\ub0b4\uae30"\ub098 \uc774\uc6a9\uad8c \ud654\uba74\uc758 "\ubb38\uc758\ud558\uae30"\uc5d0\uc11c \uc774\ub984 \ub610\ub294 \ubcc4\uce6d, \ub2f5\uc7a5 \ubc1b\uc744 \uc774\uba54\uc77c, \ubb38\uc758 \uc885\ub958\uc640 \ub0b4\uc6a9\uc744 \uc9c1\uc811 \uc801\uc5b4 \ubcf4\ub0bc \uc218 \uc788\uc5b4\uc694. \ubcf4\ub0b4\uae30\ub97c \ub204\ub974\uace0 \ubcf4\uc548 \ud655\uc778\uc744 \ub9c8\uce5c \uacbd\uc6b0\uc5d0\ub9cc \uc36c\uc6cd\uc2a4 \uc9c0\uc6d0 \uc774\uba54\uc77c(support@sunworks.kr)\ub85c \uc804\ub2ec\ub3fc\uc694.',"\ud559\uc2b5 \uae30\ub85d\uc740 \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694. \uc571 \ubc84\uc804\uacfc \ub370\uc774\ud130 \ubc84\uc804 \uac19\uc740 \uc9c4\ub2e8 \uc815\ubcf4\ub294 \uae30\ubcf8\uc73c\ub85c \uaebc\uc838 \uc788\uace0, \ud568\uaed8 \ubcf4\ub0b4\uae30\ub97c \uc9c1\uc811 \uc120\ud0dd\ud55c \uacbd\uc6b0\uc5d0\ub9cc \ubb38\uc758 \ubcf8\ubb38\uc5d0 \ub4e4\uc5b4\uac00\uc694.","\ubb38\uc758 \uc804\ub2ec\uacfc \uc2a4\ud338 \ubc29\uc9c0\uc5d0\ub294 Cloudflare Workers\xb7Turnstile, Resend, Google Workspace\ub97c \uc774\uc6a9\ud558\uba70 \uad6d\uc678\uc5d0\uc11c \ucc98\ub9ac\ub420 \uc218 \uc788\uc5b4\uc694. \ubd07\xb7\uc911\ubcf5\xb7\uacfc\ub3c4\ud55c \ubc1c\uc1a1 \ubc29\uc9c0\ub97c \uc704\ud574 IP\xb7\uc774\uba54\uc77c \ud574\uc2dc\uc640 \uc694\uccad \uc2dd\ubcc4\uc815\ubcf4\ub97c \uc77c\uc2dc\uc801\uc73c\ub85c \ucc98\ub9ac\ud574\uc694. \ud574\uc2dc\ub3c4 \uac1c\uc778\uc815\ubcf4\ub85c \ucde8\uae09\ud574\uc694.","\ubb38\uc758\uc5d0 \ud544\uc694\ud55c \uc815\ubcf4\ub9cc \uc801\uace0 \ubbfc\uac10\uc815\ubcf4\ub294 \ubcf4\ub0b4\uc9c0 \ub9c8\uc138\uc694. \ub9cc 14\uc138 \ubbf8\ub9cc \uc5b4\ub9b0\uc774\uc758 \uac1c\uc778\uc815\ubcf4\uac00 \ud3ec\ud568\ub41c \ubb38\uc758\ub294 \ubcf4\ud638\uc790\uac00 \ub300\uc2e0 \ubcf4\ub0b4 \uc8fc\uc138\uc694.","\uc811\uc218 \uacb0\uacfc\uac00 \ubd88\ud655\uc2e4\ud558\uba74 \uc774 \ud654\uba74\uc5d0\uc11c \ubcf4\uc548 \ud655\uc778 \ud6c4 \uac19\uc740 \ub0b4\uc6a9\uc73c\ub85c \ub2e4\uc2dc \ubcf4\ub0b4 \uc8fc\uc138\uc694. \uc0c8\ub85c \uc791\uc131\ud558\uba74 \uc911\ubcf5 \uc811\uc218\ub420 \uc218 \uc788\uc5b4\uc694. \uacc4\uc18d \uc2e4\ud328\ud558\uac70\ub098 \uc0ad\uc81c\ub97c \ubb38\uc758\ud558\ub824\uba74 support@sunworks.kr\ub85c \uc54c\ub824 \uc8fc\uc138\uc694.","\ubc1b\uc740 \uc758\uacac\uacfc \uc774\uba54\uc77c\uc740 \ub2f5\ubcc0\uacfc \uc571 \uac1c\uc120\uc5d0\ub9cc \uc368\uc694. \uba54\uc77c\ud568\uacfc \uc81c\uacf5\uc790\uc758 \ubcf4\uad00\xb7\uc0ad\uc81c \uae30\uac04\uc740 \ubcc4\ub3c4 \uc6b4\uc601 \uc815\ucc45\uc73c\ub85c \uc815\ud560 \uc608\uc815\uc774\uc5d0\uc694."],t.s)
B.aI0=new A.ey("9. \uc758\uacac \ubcf4\ub0b4\uae30",B.abW)
B.apP=s(["\uac1c\uc778\uc815\ubcf4\uc640 \uad00\ub828\ud574 \ubb3b\uace0 \uc2f6\uc740 \uac83\uc774 \uc788\uc73c\uba74 \uc544\ub798\ub85c \uc54c\ub824 \uc8fc\uc138\uc694.","\xb7 \uc6b4\uc601: \uc36c\uc6cd\uc2a4","\xb7 \ud68c\uc0ac \ud648\ud398\uc774\uc9c0: https://www.sunworks.kr","\xb7 \uacf5\uc2dd \uc571 \uc18c\uac1c: https://hanja.sunw.kr/","\xb7 \uc774\uba54\uc77c: support@sunworks.kr","\xb7 \uc804\ud654: 070-8717-8850","\xb7 \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ucc45\uc784\uc790: \ub0a8\uc120(\ub300\ud45c)",'\uc571 \uc548\uc758 "\uc774\uc0c1\ud574\uc694" \ubc84\ud2bc(\ubb38\ud56d \uc2e0\uace0)\uc73c\ub85c\ub3c4 \uc54c\ub824 \uc904 \uc218 \uc788\uc5b4\uc694. \uc2e0\uace0\ub294 \uc758\uacac \ubcf4\ub0b4\uae30\uc640 \uac19\uc740 \uacbd\ub85c(Cloudflare\xb7Resend)\ub85c \ubcf4\uc548 \ud655\uc778\uc744 \uac70\uccd0 \uc36c\uc6cd\uc2a4 \uc9c0\uc6d0\ud300 \uba54\uc77c\ud568\uc73c\ub85c \uc804\ub2ec\ub3fc\uc694. \uc2e0\uace0\uc5d0\ub294 \uc5b4\ub5a4 \ud55c\uc790\ub098 \ub0b1\ub9d0\uc778\uc9c0, \ubb38\uc81c \uc885\ub958, \uace0\ub978 \uc0ac\uc720, \uc9c1\uc811 \uc801\uc740 \ub0b4\uc6a9(\uc120\ud0dd), \uc571\xb7\ub370\uc774\ud130 \ubc84\uc804, \uc2e0\uace0\ud55c \uc2dc\uac01\ub9cc \ub4e4\uc5b4\uac00\uc694. \uc774\ub984\uc774\ub098 \uc5f0\ub77d\ucc98\ub294 \ubc1b\uc9c0 \uc54a\uc73c\ub2c8 \uc801\ub294 \uce78\uc5d0\ub3c4 \uac1c\uc778\uc815\ubcf4\ub294 \uc4f0\uc9c0 \ub9c8\uc138\uc694. \uc804\ub2ec\uacfc \ubcf4\uad00\uc740 9\uc808 \uc758\uacac \ubcf4\ub0b4\uae30\uc640 \uac19\uc740 \ubc29\uc2dd\uc774\uc5d0\uc694.','\ud648\uacfc \ud559\uc2b5 \ud604\ud669 \ub9e8 \uc544\ub798 "\uc624\ub958 \uc2e0\uace0"\ub85c\ub3c4 \uc571 \uc624\ub958\ub97c \uc54c\ub824 \uc904 \uc218 \uc788\uc5b4\uc694. \uc624\ub958 \uc2e0\uace0\uc5d0\ub294 \uc9c1\uc811 \uc801\uc740 \ub0b4\uc6a9, \uae30\uae30 \uc885\ub958(iOS\xb7Android\xb7\uc6f9), \uc571\xb7\ub370\uc774\ud130 \ubc84\uc804, \uc2e0\uace0\ud55c \uc2dc\uac01\ub9cc \ub4e4\uc5b4\uac00\uc694. \uc774\ub984\uc774\ub098 \uc5f0\ub77d\ucc98\ub294 \ubc1b\uc9c0 \uc54a\uc544\uc694. \ubcf4\uc548 \ud655\uc778\uacfc \uc804\ub2ec\xb7\ubcf4\uad00\uc740 \ubb38\ud56d \uc2e0\uace0\uc640 \uac19\uc544\uc694.'],t.s)
B.aHN=new A.ey("10. \uad81\uae08\ud55c \uc810\uc774 \uc788\uc73c\uba74",B.apP)
B.apW=s(["\xb7 1.0 (2026\ub144 9\uc6d4 8\uc77c \uc2dc\ud589) \u2014 \ucc98\uc74c \ub9cc\ub4e4\uc5c8\uc5b4\uc694.","\xb7 1.1 (2026\ub144 9\uc6d4 26\uc77c \uc2dc\ud589) \u2014 \uc5f0\uad6c \ucc38\uc5ec(\uc120\ud0dd) \uc808\uc744 \ub354\ud588\uc5b4\uc694.","\xb7 1.2 (2026\ub144 10\uc6d4 2\uc77c \uc2dc\ud589) \u2014 \uc6b4\uc601 \ud68c\uc0ac\uc640 \uacf5\uc2dd \uc0ac\uc774\ud2b8, \ubb38\uc758 \uc774\uba54\uc77c\uc744 \uc548\ub0b4\ud588\uc5b4\uc694.","\xb7 1.3 (2026\ub144 10\uc6d4 11\uc77c \uc2dc\ud589) \u2014 \uc758\uacac \ubcf4\ub0b4\uae30 \uc808\uc744 \ub354\ud588\uc5b4\uc694.","\xb7 1.4 (2026\ub144 10\uc6d4 16\uc77c \uc2dc\ud589) \u2014 \uc804\ud654\ubc88\ud638\uc640 \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ucc45\uc784\uc790\ub97c \uc548\ub0b4\ud588\uc5b4\uc694.","\xb7 1.5 (2026\ub144 10\uc6d4 22\uc77c \uc2dc\ud589) \u2014 \uc624\ub958 \uc2e0\uace0\ub97c \uc548\ub0b4\ud588\uc5b4\uc694.","\xb7 1.6 (2026\ub144 10\uc6d4 27\uc77c \uc2dc\ud589) \u2014 \uc5f0\uad6c \ucc38\uc5ec(\uc120\ud0dd) \uc808\uc744 \ube90\uc5b4\uc694.","\ubc29\uce68\uc744 \uace0\uce60 \ub54c\ub294 \uc571 \uc548\uc758 \uc774 \ud654\uba74\uacfc \uc6f9 \ud398\uc774\uc9c0\ub97c \ud568\uaed8 \uace0\uce58\uace0, \ubc14\ub010 \ub0a0\uc9dc\ub97c \uc5ec\uae30\uc5d0 \uc801\uc744\uac8c\uc694."],t.s)
B.aHU=new A.ey("11. \uac1c\uc815 \uc774\ub825",B.apW)
